using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Revert to keep compatibility with
            // existing 500K documents and direct SQL queries that filter on
            // c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id values no longer include the
            // discriminator prefix. Previously "Product|123", now just "123".
            // Revert to the EF Core 8 format so existing documents remain
            // accessible without data migration.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve EF Core 8 id format ("EntityName|KeyValue") globally
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdValueGeneratorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

